import click
from click.testing import CliRunner


class Foo:
    pass


class Bar:
    pass


def test_flag_value_class_default_not_instantiated():
    seen = []

    @click.command()
    @click.option("--foo", "ty", flag_value=Foo, type=click.UNPROCESSED, default=True)
    @click.option("--bar", "ty", flag_value=Bar, type=click.UNPROCESSED)
    def main(ty):
        seen.append(ty)

    result = CliRunner().invoke(main, [])
    assert result.exit_code == 0, result.output
    assert seen == [Foo]

import click


class StrictVersion:
    """Mimics semver.Version: __eq__ parses string operands and raises on invalid ones."""

    def __init__(self, s):
        self.s = s

    def __str__(self):
        return self.s

    def __eq__(self, other):
        if isinstance(other, str):
            parts = other.split(".")
            if len(parts) != 3 or not all(p.isdigit() for p in parts):
                raise ValueError(f"{other!r} is not valid SemVer string")
            return self.s == other
        return NotImplemented

    __hash__ = None


def test_help_with_object_default_whose_eq_raises_on_str():
    @click.command()
    @click.option("--version", default=StrictVersion("1.0.0"), show_default=True)
    def cli(version):
        pass

    ctx = click.Context(cli)
    help_text = cli.get_help(ctx)
    assert "1.0.0" in help_text

import click

import click._termui_impl


def test_progressbar_show_pos_full_completion_with_update_min_steps(runner, monkeypatch):
    @click.command()
    def cli():
        with click.progressbar(
            range(20),
            show_pos=True,
            update_min_steps=7,
        ) as bar:
            for _ in bar:
                pass

    monkeypatch.setattr(click._termui_impl, "isatty", lambda _: True)
    output = runner.invoke(cli, []).output

    lines = [line for line in output.split("\r") if "[" in line]
    assert "20/20" in lines[-1]

import click
from click.testing import CliRunner


@click.command()
def cmd_confirm():
    click.confirm(click.style("Hello World!", fg="green"), abort=True)


def test_confirm_strips_ansi_with_color_false():
    runner = CliRunner()
    result = runner.invoke(cmd_confirm, input="Y", color=False)
    assert result.output == "Hello World! [y/N]: Y\n"
